function wdWords(){
  return ["APPLE","BRAVE","CRANE","DREAM","EAGLE","FLAME","GRAPE","HOUSE","INPUT","JUICE",
    "KNIFE","LEMON","MOUSE","NIGHT","OCEAN","PIANO","QUERY","RIVER","STONE","TIGER",
    "ULTRA","VIVID","WHALE","XENON","YOUTH","ZEBRA","CODER","DEBUG","ARRAY","STACK",
    "QUEUE","GRAPH","TOKEN","CACHE","PIXEL","LOGIC","SHELL","LINUX","REGEX","ASYNC"];
}
function wdPick(seed){
  var ws=wdWords();
  var s=Math.abs(Math.floor(Number(seed)||0));
  return ws[s%ws.length];
}
function wdValid(guess){
  return /^[A-Za-z]{5}$/.test(String(guess||''));
}
function wdScore(guess, answer){
  guess=String(guess||'').toUpperCase(); answer=String(answer||'').toUpperCase();
  if(guess.length!==5 || answer.length!==5) return null;
  var res=['b','b','b','b','b'];
  var remain={};
  for(var i=0;i<5;i++){
    if(guess[i]===answer[i]){ res[i]='g'; }
    else { remain[answer[i]]=(remain[answer[i]]||0)+1; }
  }
  for(var j=0;j<5;j++){
    if(res[j]==='b' && remain[guess[j]]>0){ res[j]='y'; remain[guess[j]]--; }
  }
  return res.join('');
}
function wdWin(score){ return score==='ggggg'; }
function wdKeyStates(history){
  var rank={b:1,y:2,g:3}, st={};
  (history||[]).forEach(function(h){
    for(var i=0;i<5;i++){
      var ch=h.guess[i], sc=h.score[i];
      if(!st[ch] || rank[sc]>rank[st[ch]]) st[ch]=sc;
    }
  });
  return st;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { wdWords:wdWords, wdPick:wdPick, wdValid:wdValid, wdScore:wdScore, wdWin:wdWin, wdKeyStates:wdKeyStates };
}
if (typeof window !== 'undefined') {
  window.WordleForgePure = { wdWords:wdWords, wdPick:wdPick, wdValid:wdValid, wdScore:wdScore, wdWin:wdWin, wdKeyStates:wdKeyStates };
}
